"""도메인과 프로젝트의 auto-generated file: 그 스코프의 auto-generated file 권한으로 목록을 조회하기."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Any, Literal, override

import pytest

from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileEntityType
from ai.backend.common.data.entity.domain import DomainEntityType, DomainID
from ai.backend.common.data.entity.project import ProjectID
from ai.backend.common.data.entity.types import EntityIdentifier, EntityType
from ai.backend.common.data.entity.user import UserID
from ai.backend.common.dto.manager.config.response import DotfileListItem
from ai.backend.manager.api.adapters.auto_generated_file.adapter import AutoGeneratedFileAdapter
from ai.backend.manager.data.permission.types import Permission
from ai.backend.manager.data.user.types import UserData
from ai.backend.manager.errors.permission import NotEnoughPermission
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.testutils.scenario_steps import (
    Answered,
    Given,
    Same,
    Says,
    Scenario,
    Then,
    Verdict,
    When,
)
from bai_scenario.components.answers import MissingResponse, TheCallIsRefused
from bai_scenario.components.domain import WAS_HERE, SomeoneOf
from bai_scenario.runner.acting import ActingAs
from bai_scenario.runner.planting import TestSeedingSession
from bai_scenario.runner.steps import run_scenario
from bai_scenario.seeds.domain.domain import TestSeedDomain
from bai_scenario.seeds.project.project import TestSeedProject
from bai_scenario.seeds.rbac.role import TestSeedPermission, TestSeedRole
from bai_scenario.seeds.resource_policy.project import TestSeedProjectPolicy
from bai_scenario.seeds.user.fields import (
    TestSeedConfigFileOf,
    TestSeedConfigFileRevisionOf,
    TestSeedDefaultConfigFileOf,
)

CONFIG_PATH = ".vimrc"
CONFIG_PERMISSION = "644"
CONFIG_DATA = "set number\n"

type Owner = Literal["domain", "project"]
type Listed = list[DotfileListItem]


@dataclass(frozen=True)
class AnOrganizationsFileAndAReader:
    """auto-generated file 하나를 own 하는 도메인이나 프로젝트와, 그 목록을 조회하는 사용자."""

    owner: EntityIdentifier
    reader: UserData


@dataclass(frozen=True)
class AReaderOfAnOrganizationsFile(Given[Any, AnOrganizationsFileAndAReader]):
    """도메인 하나와, ``owner`` 가 프로젝트면 그 아래 프로젝트 하나. 그 owner 는 default 로 지정된
    auto-generated file 하나를 갖고, 사용자는 그 owner 스코프의 역할로 ``grants`` 를 받는다."""

    owner: Owner
    grants: Sequence[tuple[EntityType, Permission]]

    @override
    def describe(self) -> str:
        owner_ko = "도메인" if self.owner == "domain" else "프로젝트"
        owner_en = "domain" if self.owner == "domain" else "project"
        names = ", ".join(
            f"{entity_type} {permission.name}" for entity_type, permission in self.grants
        )
        return Says(
            f"{owner_ko} 하나는 default 로 지정된 {CONFIG_PATH} auto-generated file 을 갖고 있습니다"
            f"(권한 {CONFIG_PERMISSION}, revision 1 의 내용 {CONFIG_DATA!r}), "
            f"사용자는 그 {owner_ko} 스코프의 역할로 {names} 권한을 받았습니다",
            english=(
                f"one {owner_en} holds a {CONFIG_PATH} auto-generated file set as default "
                f"(permission {CONFIG_PERMISSION}, revision 1 holding {CONFIG_DATA!r}), and a "
                f"user holds the {names} permissions through a role in that {owner_en}'s scope"
            ),
        )

    @override
    async def lay(self, seeding: Any) -> AnOrganizationsFileAndAReader:
        domain = await seeding.creating(TestSeedDomain(name_hint="home", description=WAS_HERE))
        reader = await seeding.within(SomeoneOf(domain))
        holder = domain
        owner: EntityIdentifier = DomainID(seeding.made(domain).id)
        if self.owner == "project":
            policy = await seeding.once(TestSeedProjectPolicy())
            holder = await seeding.creating_from_two(TestSeedProject(), domain, policy)
            owner = ProjectID(seeding.made(holder).id)
        file = await seeding.creating_from(
            TestSeedConfigFileOf(lambda _: owner, path=CONFIG_PATH),
            holder,
        )
        await seeding.adding(
            TestSeedConfigFileRevisionOf(
                data=CONFIG_DATA, perm=CONFIG_PERMISSION, creator_id=UserID(seeding.made(reader).id)
            ),
            file,
        )
        await seeding.creating_from(TestSeedDefaultConfigFileOf(path=CONFIG_PATH), file)
        role = await seeding.creating_from(
            TestSeedRole(lambda _: owner, name_hint="config-file-reader"), holder
        )
        for entity_type, permission in self.grants:
            await seeding.adding(TestSeedPermission(entity_type, permission), role)
        await seeding.granting(
            role, reader, role_id=lambda one: one.id, user_id=lambda one: UserID(one.id)
        )
        return AnOrganizationsFileAndAReader(owner=owner, reader=seeding.made(reader))


@dataclass(frozen=True)
class ListingTheOrganizationsFiles(
    When[AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]
):
    """그 owner 의 default 로 지정된 auto-generated file 목록을 조회한다."""

    @override
    def operation(self) -> str:
        return "list_default_auto_generated_files"

    @override
    def describe(self, laid: AnOrganizationsFileAndAReader) -> str:
        return Says(
            f"{laid.reader.username}이 그 owner 의 default 로 지정된 auto-generated file 목록을 "
            "조회합니다",
            english=(
                f"{laid.reader.username} lists the auto-generated files of the owner set as default"
            ),
        )

    @override
    async def call(
        self, adapter: AutoGeneratedFileAdapter, laid: AnOrganizationsFileAndAReader
    ) -> Listed:
        with ActingAs(laid.reader):
            return await adapter.list_default_auto_generated_files(laid.owner)


@dataclass(frozen=True)
class TheOrganizationsFileIsListed(Then[AnOrganizationsFileAndAReader, Listed]):
    """그 owner 의 default 파일 하나가 path, 권한, 내용과 함께 온다."""

    @override
    def says(self) -> str:
        return Says(
            "그 owner 의 default 파일 하나가 path, 권한, 내용과 함께 옵니다",
            english="the owner's one default file comes back with its path, permission and content",
        )

    @override
    def look(
        self, laid: AnOrganizationsFileAndAReader, answered: Answered[Listed]
    ) -> list[Verdict]:
        response = answered.response
        if response is None:
            return [MissingResponse(answered.raised)]
        return [
            Same(
                "response",
                [item.model_dump() for item in response],
                [{"path": CONFIG_PATH, "permission": CONFIG_PERMISSION, "data": CONFIG_DATA}],
            )
        ]


type OrganizationStep = Scenario[
    TestSeedingSession, AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed
]


@dataclass(frozen=True)
class AUserGrantedFileReadInADomainListsItsFiles(
    Scenario[TestSeedingSession, AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-file-read-in-a-domain-lists-its-auto-generated-files"

    @override
    def describe(self) -> str:
        return Says(
            "도메인 스코프에서 auto-generated file READ 를 받은 사용자가 그 도메인의 파일 목록을 "
            "조회하면, default 로 지정된 파일이 옵니다",
            english=(
                "when a user holding READ on auto-generated files in a domain's scope lists the "
                "domain's files, the file set as default comes back"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, AnOrganizationsFileAndAReader]:
        return AReaderOfAnOrganizationsFile(
            owner="domain", grants=((AutoGeneratedFileEntityType(), Permission.READ),)
        )

    @override
    def when(self) -> When[AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]:
        return ListingTheOrganizationsFiles()

    @override
    def then(self) -> Then[AnOrganizationsFileAndAReader, Listed]:
        return TheOrganizationsFileIsListed()


@dataclass(frozen=True)
class AUserGrantedOnlyDomainReadMayNotListItsFiles(
    Scenario[TestSeedingSession, AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-only-domain-read-may-not-list-its-auto-generated-files"

    @override
    def describe(self) -> str:
        return Says(
            "도메인 READ 만 받은 사용자가 그 도메인의 auto-generated file 목록을 조회하려 하면, "
            "권한 부족으로 거부됩니다",
            english=(
                "a user holding only READ on the domain who tries to list the domain's "
                "auto-generated files is rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, AnOrganizationsFileAndAReader]:
        return AReaderOfAnOrganizationsFile(
            owner="domain", grants=((DomainEntityType(), Permission.READ),)
        )

    @override
    def when(self) -> When[AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]:
        return ListingTheOrganizationsFiles()

    @override
    def then(self) -> Then[AnOrganizationsFileAndAReader, Listed]:
        return TheCallIsRefused(NotEnoughPermission)


@dataclass(frozen=True)
class AUserGrantedFileReadInAProjectListsItsFiles(
    Scenario[TestSeedingSession, AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-file-read-in-a-project-lists-its-auto-generated-files"

    @override
    def describe(self) -> str:
        return Says(
            "프로젝트 스코프에서 auto-generated file READ 를 받은 사용자가 그 프로젝트의 파일 목록을 "
            "조회하면, default 로 지정된 파일이 옵니다",
            english=(
                "when a user holding READ on auto-generated files in a project's scope lists "
                "the project's files, the file set as default comes back"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, AnOrganizationsFileAndAReader]:
        return AReaderOfAnOrganizationsFile(
            owner="project", grants=((AutoGeneratedFileEntityType(), Permission.READ),)
        )

    @override
    def when(self) -> When[AnOrganizationsFileAndAReader, AutoGeneratedFileAdapter, Listed]:
        return ListingTheOrganizationsFiles()

    @override
    def then(self) -> Then[AnOrganizationsFileAndAReader, Listed]:
        return TheOrganizationsFileIsListed()


SCENARIOS: list[OrganizationStep] = [
    AUserGrantedFileReadInADomainListsItsFiles(),
    AUserGrantedOnlyDomainReadMayNotListItsFiles(),
    AUserGrantedFileReadInAProjectListsItsFiles(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_organization_files(
    scenario: OrganizationStep,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
